const isOwner = (u) => OWNERS.has(u);
const isAdmin = (u) => isOwner(u) || !!(getUser(u) && db.users[u].admin);
const roleOf = (u) => (isOwner(u) ? 'owner' : isAdmin(u) ? 'admin' : 'user');
const adminList = () => Object.keys(db.users).filter(isAdmin);

// ============================================================== авторизация ==

function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 64).toString('hex');
}

function checkPassword(user, password) {
  const a = Buffer.from(hashPassword(password, user.salt), 'hex');
  const b = Buffer.from(user.hash, 'hex');
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

function newToken(username) {
  const token = crypto.randomBytes(32).toString('hex');
  db.sessions[token] = { user: username, ts: Date.now() };
  touch('sessions', token);
  // не храним больше N сессий на человека
  const mine = Object.entries(db.sessions).filter(([, s]) => s.user === username).sort((a, b) => a[1].ts - b[1].ts);
  while (mine.length > MAX_SESSIONS_PER_USER) {
    const [old] = mine.shift();
    delete db.sessions[old];
    touch('sessions', old);
  }
  return token;
}

function dropSessions(username) {
  for (const [t, s] of Object.entries(db.sessions)) {
    if (s.user === username) {
      delete db.sessions[t];
      touch('sessions', t);
    }
  }
}

// ================================================================== клиенты ==

const clients = new Map(); // username -> Set<ws>

const isOnline = (u) => !!clients.get(u) && clients.get(u).size > 0;

function sendTo(username, payload) {
  const set = clients.get(username);
  if (!set) return;
  const data = JSON.stringify(payload);
  for (const ws of set) if (ws.readyState === 1) ws.send(data);
}

function sendWs(ws, payload) {
  if (ws.readyState === 1) ws.send(JSON.stringify(payload));
}

function broadcastAll(payload) {
  for (const username of clients.keys()) sendTo(username, payload);
}

function kick(username, reason) {
  const set = clients.get(username);
  if (!set) return;
  for (const ws of [...set]) {
    sendWs(ws, { type: 'banned', reason });
    try { ws.close(); } catch { /* ignore */ }
  }
}

function subOf(u) {
  const x = getUser(u);
  return x && x.sub && x.sub.until > Date.now() ? x.sub : null;
}
const tierOf = (u) => (subOf(u) || {}).plan || null;
function subsMap() {
  const o = {};
  for (const [n, u] of Object.entries(db.users)) {
    if (u.sub && u.sub.until > Date.now() && !u.banned) o[n] = { plan: u.sub.plan, until: u.sub.until };
  }
  return o;
}
const bonusFor = (u) => Math.round(DAILY_BONUS * (tierOf(u) === 'premium' ? 2 : tierOf(u) === 'plus' ? 1.5 : 1));
const giftPrice = (u, g) => Math.max(1, Math.round(g.price * (tierOf(u) === 'premium' ? 0.9 : 1)));
function giftsView(u) {
  const list = (getUser(u) && db.users[u].gifts) || [];
  return list.slice(0, 100).map((e) => {
    const g = GIFTS.find((x) => x.id === e.gift) || { emoji: '🎁', name: 'Подарок' };
    return { id: e.id, gid: e.gift, emoji: g.emoji, name: g.name, from: e.from, ts: e.ts, note: e.note || '' };
  });
}
const fmtDate = (ts) => {
  const d = new Date(ts + 3 * 3600000);
  return `${String(d.getUTCDate()).padStart(2, '0')}.${String(d.getUTCMonth() + 1).padStart(2, '0')}.${d.getUTCFullYear()}`;
};

function cleanAvatar(a) {
  if (!a || typeof a !== 'object') return null;
  const out = {};
  if (typeof a.e === 'string') {
    const e = Array.from(a.e.replace(/[\u0000-\u001f]/g, '').trim()).slice(0, 8).join('');
    if (e) out.e = e;
  }
  if (typeof a.c === 'string' && /^#[0-9a-fA-F]{6}$/.test(a.c)) out.c = a.c;
  if (typeof a.p === 'string' && a.p.length <= 14000 && /^data:image\/jpeg;base64,[A-Za-z0-9+/]+={0,2}$/.test(a.p)) out.p = a.p;
  return Object.keys(out).length ? out : null;
}
function avatarMap() {
  const o = {};
  for (const [n, u] of Object.entries(db.users)) if (u.avatar && !u.banned) o[n] = u.avatar;
  return o;
}

// радужный ник: право есть у владельцев и тех, кому его выдал владелец; включать и выключать можно самому
const canRainbow = (u) => isOwner(u) || !!(getUser(u) && db.users[u].rainbowGrant);
const rainbowOn = (u) => canRainbow(u) && !(getUser(u) && db.users[u].rainbowOff);
const rainbowList = () => Object.keys(db.users).filter((n) => !db.users[n].banned && rainbowOn(n));

function findByEmail(email) {
  if (!email) return null;
  return Object.keys(db.users).find((n) => db.users[n].email === email) || null;
}

function userMe(u) {
  const x = getUser(u);
  const sub = subOf(u);
  return {
    coins: x ? x.coins : 0,
    lastBonus: x ? x.lastBonus || 0 : 0,
    role: roleOf(u),
    sub: sub ? { plan: sub.plan, until: sub.until } : null,
    bonus: bonusFor(u),
    giftCount: x && Array.isArray(x.gifts) ? x.gifts.length : 0,
    bio: (x && x.bio) || '',
    avatar: (x && x.avatar) || null,
    email: (x && x.email) || '',
    rainbowCan: canRainbow(u),
    rainbow: rainbowOn(u),
  };
}

function pushBalance(u) {
  sendTo(u, { type: 'balance', ...userMe(u) });
}

// ===================================================================== чаты ==

const dmId = (a, b) => 'dm:' + [a, b].sort().join(':');

function getOrCreateDm(a, b) {
  const id = dmId(a, b);
  if (!getChat(id)) {
    db.chats[id] = { id, type: 'dm', name: '', members: [a, b], messages: [], reads: { [a]: 0, [b]: 0 } };
    touch('chats', id);
  }
  return db.chats[id];
}

function ensureAnnounce() {
  if (!getChat(ANNOUNCE_ID)) {
    db.chats[ANNOUNCE_ID] = { id: ANNOUNCE_ID, type: 'channel', name: 'Объявления', members: [], messages: [], reads: {} };
    touch('chats', ANNOUNCE_ID);
  }
  return db.chats[ANNOUNCE_ID];
}

function addToAnnounce(user) {
  const c = ensureAnnounce();
  if (!c.members.includes(user)) {
    c.members.push(user);
    c.reads[user] = c.messages.length; // старые объявления не считаем непрочитанными
    touch('chats', c.id);
  }
}

function chatView(chat, user) {
  const last = chat.messages.length ? chat.messages[chat.messages.length - 1] : null;
  const reads = chat.reads[user] || 0;
  let pinned = null;
  if (chat.pinned) {
    const pm = chat.messages.find((x) => x.id === chat.pinned);
    if (pm && !pm.deleted) pinned = { id: pm.id, from: pm.from, text: previewOf(pm).slice(0, 100) };
  }
  const view = {
    id: chat.id,
    type: chat.type,
    members: chat.members,
    reads: chat.reads,
    total: chat.messages.length,
    unread: Math.max(0, chat.messages.length - reads),
    pinned,
    last: last ? { from: last.from, text: previewOf(last), ts: last.ts, system: !!last.system, deleted: !!last.deleted } : null,
  };
  if (chat.type === 'dm') {
    const peer = chat.members.find((m) => m !== user) || user;
    view.name = peer;
    view.peer = peer;
    view.lastSeen = (getUser(peer) && db.users[peer].lastSeen) || null;
  } else {
    view.name = chat.name;
    view.owner = chat.owner;
  }
  return view;
}

function chatsFor(user) {
  return Object.values(db.chats)
    .filter((c) => c.members.includes(user) && (c.type === 'group' || c.messages.length > 0))
    .map((c) => chatView(c, user));
}

function trimChat(chat) {
  let drop = 0;
  let chars = chat.messages.reduce((n, m) => n + (m.text ? m.text.length : 0), 0);
  while (chat.messages.length - drop > 1 && (chat.messages.length - drop > HISTORY_LIMIT || chars > HISTORY_CHARS)) {
    chars -= chat.messages[drop].text ? chat.messages[drop].text.length : 0;
    drop++;
  }
  if (!drop) return;
  chat.messages.splice(0, drop);
  for (const m of chat.members) chat.reads[m] = Math.max(0, (chat.reads[m] || 0) - drop);
}

function pushMessage(chat, message) {
  chat.messages.push(message);
  trimChat(chat);
  touch('chats', chat.id);
  for (const member of chat.members) {
    sendTo(member, { type: 'message', chatId: chat.id, message, chat: chatView(chat, member) });
  }
}

function broadcastUpdate(chat, message) {
  touch('chats', chat.id);
  for (const member of chat.members) {
    sendTo(member, { type: 'msg_update', chatId: chat.id, message, chat: chatView(chat, member) });
  }
}

function markRead(chat, user) {
  if ((chat.reads[user] || 0) === chat.messages.length) return false;
  chat.reads[user] = chat.messages.length;
  touch('chats', chat.id);
  for (const member of chat.members) sendTo(member, { type: 'reads', chatId: chat.id, reads: chat.reads });
  return true;
}

function removeChat(chat) {
  for (const msg of chat.messages) if (msg.media) deleteMedia(msg.media.id);
  for (const m of chat.members) sendTo(m, { type: 'chat_removed', chatId: chat.id });
  delete db.chats[chat.id];
  touch('chats', chat.id);
}

function removeUser(name) {
  delete db.users[name];
  touch('users', name);
  dropSessions(name);
  kick(name, 'Аккаунт удалён администратором');
  for (const chat of Object.values(db.chats)) {
    if (!chat.members.includes(name)) continue;
    if (chat.type === 'dm') {
      removeChat(chat);
      continue;
    }
    chat.members = chat.members.filter((m) => m !== name);
    delete chat.reads[name];
    for (const m of chat.messages) {
      if (m.from === name) m.from = 'удалённый аккаунт';
      if (m.replyTo && m.replyTo.from === name) m.replyTo.from = 'удалённый аккаунт';
      if (m.reactions) {
        for (const e of Object.keys(m.reactions)) {
          m.reactions[e] = m.reactions[e].filter((u) => u !== name);
          if (!m.reactions[e].length) delete m.reactions[e];
        }
      }
    }
    if (chat.type === 'group' && chat.members.length < 2) {
      removeChat(chat);
    } else {
      touch('chats', chat.id);
      for (const member of chat.members) sendTo(member, { type: 'chat_update', chat: chatView(chat, member) });
    }
  }
}

// =================================================================== обработка ==

function authOk(ws, username, token) {
  ws.user = username;
  if (!clients.has(username)) clients.set(username, new Set());
  const wasOnline = isOnline(username);
  clients.get(username).add(ws);
  sendWs(ws, {
    type: 'auth_ok',
    username,
    token,
    me: userMe(username),
    cfg: {
      dailyBonus: DAILY_BONUS, dailyMs: DAY_MS, reactions: REACTIONS, stickers: STICKERS,
      photo: { free: [1280, 560], plus: [2560, 1600], premium: [16384, 5000] },
      gifts: GIFTS, plans: PLANS, pStickers: PREMIUM_STICKERS, pReactions: PREMIUM_REACTIONS, giftSell: GIFT_SELL,
    },
    subs: subsMap(),
    rainbows: rainbowList(),
    avatars: avatarMap(),
    admins: adminList(),
    chats: chatsFor(username),
    online: [...clients.keys()].filter(isOnline),
  });
  if (!wasOnline) broadcastAll({ type: 'presence', user: username, online: true });
}

function allowRate(ws) {
  const t = Date.now();
  if (!ws.rl || t - ws.rl.start > 10000) ws.rl = { n: 0, start: t };
  ws.rl.n++;
  return ws.rl.n <= 120;
}

function adminSnapshot(query) {
  const q = String(query || '').toLowerCase();
  const users = Object.entries(db.users)
    .filter(([n]) => !q || n.includes(q))
    .map(([n, u]) => ({
      username: n,
      coins: u.coins || 0,
      online: isOnline(n),
      banned: !!u.banned,
      role: roleOf(n),
      sub: !!subOf(n),
      rainbow: canRainbow(n),
      created: u.created || 0,
      lastSeen: u.lastSeen || null,
    }))
    .sort((a, b) => b.created - a.created)
    .slice(0, 300);
  let messages = 0;
  for (const c of Object.values(db.chats)) messages += c.messages.length;
  let coins = 0;
  for (const u of Object.values(db.users)) coins += u.coins || 0;
  return {
    type: 'admin_users',
    users,
    stats: {
      users: Object.keys(db.users).length,
      online: clients.size,
      chats: Object.keys(db.chats).length,
      messages,
      coins,
      storage: USE_REDIS ? 'Upstash Redis (данные сохраняются)' : 'файл (на бесплатном Render может стираться)',
    },
  };
}

function adminChatList() {
  return {
    type: 'admin_chats',
    chats: Object.values(db.chats)
      .map((c) => ({
        id: c.id,
        type: c.type,
        name: c.type === 'dm' ? c.members.join(' ↔ ') : c.name,
        members: c.members.length,
        total: c.messages.length,
        last: c.messages.length ? c.messages[c.messages.length - 1].ts : 0,
      }))
      .sort((a, b) => b.last - a.last)
      .slice(0, 300),
  };
}

// может ли `me` управлять аккаунтом `target` (бан, удаление, пароль)
function canManage(me, target) {
  if (!target || me === target) return false;
  if (isOwner(target)) return false;
  if (isAdmin(target) && !isOwner(me)) return false;
  return true;
}

function handle(ws, m) {
  if (!m || typeof m !== 'object') return;

  // ------------------------------------------------------ без авторизации --
  if (m.type === 'register') {
    const username = String(m.username || '').trim().toLowerCase();
    const password = String(m.password || '');
    if (!USERNAME_RE.test(username)) {
      return sendWs(ws, { type: 'auth_error', error: 'Имя: 3–20 символов, латиница, цифры и _' });
    }
    if (password.length < 6) {
      return sendWs(ws, { type: 'auth_error', error: 'Пароль должен быть не короче 6 символов' });
    }
    if (getUser(username) || (RESERVED.has(username) && !isOwner(username)) || has(Object.prototype, username)) {
      return sendWs(ws, { type: 'auth_error', error: 'Это имя уже занято' });
    }
    const email = String(m.email || '').trim().toLowerCase();
    if (email && (email.length > 120 || !EMAIL_RE.test(email))) {
      return sendWs(ws, { type: 'auth_error', error: 'Проверьте адрес почты' });
    }
    if (email && findByEmail(email)) {
      return sendWs(ws, { type: 'auth_error', error: 'Эта почта уже используется' });
    }
    const salt = crypto.randomBytes(16).toString('hex');
    db.users[username] = {
      salt,
      hash: hashPassword(password, salt),
      created: Date.now(),
      lastSeen: null,
      coins: START_COINS,
      lastBonus: 0,
      admin: false,
      banned: false,
      ...(email ? { email } : {}),
    };
    touch('users', username);
    addToAnnounce(username);
    return authOk(ws, username, newToken(username));
  }

  if (m.type === 'login') {
    const ident = String(m.username || '').trim().toLowerCase();
    const username = ident.includes('@') ? findByEmail(ident) : ident;
    const user = username && getUser(username);
    if (!user || !checkPassword(user, String(m.password || ''))) {
      return sendWs(ws, { type: 'auth_error', error: 'Неверное имя (почта) или пароль' });
    }
    if (user.banned) return sendWs(ws, { type: 'auth_error', error: 'Аккаунт заблокирован администратором' });
    return authOk(ws, username, newToken(username));
  }

  if (m.type === 'resume') {
    const s = typeof m.token === 'string' && has(db.sessions, m.token) ? db.sessions[m.token] : null;
    const user = s && getUser(s.user);
    if (!user) return sendWs(ws, { type: 'auth_error', error: 'Сессия истекла, войдите заново', resume: true });
    if (user.banned) return sendWs(ws, { type: 'auth_error', error: 'Аккаунт заблокирован администратором', resume: true });
    return authOk(ws, s.user, m.token);
  }

  // ----------------------------------------------------------- с авторизацией --
  const me = ws.user;
  const meU = me && getUser(me);
  if (!meU || meU.banned) return;
  if (!allowRate(ws)) return sendWs(ws, { type: 'error', error: 'Слишком часто, подождите немного' });

  const err = (error) => sendWs(ws, { type: 'error', error });
  const info = (text) => sendWs(ws, { type: 'info', text });
  const memberChat = () => {
    const c = getChat(m.chatId);
    return c && c.members.includes(me) ? c : null;
  };
  const findMsg = (chat, id) => chat.messages.find((x) => x.id === id);
  // цитата сообщения, на которое отвечают
  const makeReply = (chat, id) => {
    if (!id) return null;
    const t = findMsg(chat, String(id));
    return t && !t.deleted ? { id: t.id, from: t.from, text: previewOf(t).slice(0, 120) } : null;
  };
  // можно ли писать в этот чат (канал — только админам, личный — если собеседник доступен)
  const canPost = (chat) => {
    if (chat.type === 'channel' && !isAdmin(me)) return 'В этом канале пишут только администраторы';
    if (chat.type === 'dm') {
      const peer = chat.members.find((x) => x !== me);
      if (!getUser(peer) || db.users[peer].banned) return 'Пользователь недоступен';
    }
    return null;
  };

  switch (m.type) {
    // ---------------------------------------------------------------- люди --
    case 'search': {
      const q = String(m.query || '').trim().toLowerCase();
      const users = Object.keys(db.users)
        .filter((u) => u !== me && !db.users[u].banned && (q === '' || u.includes(q)))
        .slice(0, m.ctx === 'contacts' ? 200 : 20)
        .map((u) => ({ username: u, online: isOnline(u) }));
      return sendWs(ws, { type: 'search_result', query: q, ctx: m.ctx || null, users });
    }

    case 'open_dm': {
      const peer = String(m.username || '').toLowerCase();
      const pu = getUser(peer);
      if (!pu || peer === me || pu.banned) return err('Пользователь не найден');
      return sendWs(ws, { type: 'chat_open', chat: chatView(getOrCreateDm(me, peer), me) });
    }

    case 'create_group': {
      const name = String(m.name || '').trim().slice(0, 50);
      if (!name) return err('Введите название группы');
      const members = [...new Set([me, ...(Array.isArray(m.members) ? m.members : [])])]
        .map((u) => String(u).toLowerCase())
        .filter((u) => getUser(u) && !db.users[u].banned);
      if (members.length < 2) return err('Добавьте хотя бы одного участника');
      const id = 'g:' + newId();
      const chat = { id, type: 'group', name, owner: me, members, messages: [], reads: {} };
      for (const u of members) chat.reads[u] = 0;
      db.chats[id] = chat;
      pushMessage(chat, { id: newId(), from: me, text: `${me} создал(а) группу «${name}»`, ts: Date.now(), system: true });
      return sendWs(ws, { type: 'chat_open', chat: chatView(chat, me) });
    }

    // ----------------------------------------------------------- сообщения --
    case 'history': {
      const chat = memberChat();
      if (!chat) return;
      return sendWs(ws, { type: 'history', chatId: chat.id, messages: chat.messages, reads: chat.reads });
    }

    case 'send': {
      const text = String(m.text || '').trim().slice(0, MAX_TEXT);
      const chat = memberChat();
      if (!text || !chat) return;
      if (chat.type === 'channel' && !isAdmin(me)) return err('В этом канале пишут только администраторы');
      if (chat.type === 'dm') {
        const peer = chat.members.find((x) => x !== me);
        if (!getUser(peer) || db.users[peer].banned) return err('Пользователь недоступен');
      }
      const message = { id: newId(), from: me, text, ts: Date.now() };
      if (m.rainbow && (tierOf(me) === 'premium' || isOwner(me))) message.rainbow = true;
      const reply = makeReply(chat, m.replyTo);
      if (reply) message.replyTo = reply;
      pushMessage(chat, message);
      markRead(chat, me);
      return;
    }

    case 'edit': {
      const chat = memberChat();
      const text = String(m.text || '').trim().slice(0, MAX_TEXT);
      if (!chat || !text) return;
      const msg = findMsg(chat, String(m.id));
      if (!msg || msg.system || msg.deleted || msg.kind || msg.from !== me) return err('Это сообщение нельзя изменить');
      if (msg.text === text) return;
      msg.text = text;
      msg.edited = Date.now();
      return broadcastUpdate(chat, msg);
    }

    case 'delete': {
      const chat = memberChat();
      if (!chat) return;
      const msg = findMsg(chat, String(m.id));
      if (!msg || msg.deleted) return;
      const own = msg.from === me && !msg.system;
      if (!own && !isAdmin(me)) return err('Нет прав на удаление');
      msg.deleted = true;
      msg.deletedBy = own ? 'self' : 'admin';
      msg.text = '';
      if (msg.media) deleteMedia(msg.media.id);
      delete msg.media;
      delete msg.poll;
      delete msg.sticker;
      delete msg.kind;
      delete msg.reactions;
      delete msg.replyTo;
      delete msg.edited;
      if (chat.pinned === msg.id) chat.pinned = null;
      // цитаты на удалённое сообщение больше не показывают его текст
      for (const other of chat.messages) {
        if (other.replyTo && other.replyTo.id === msg.id) other.replyTo.text = 'сообщение удалено';
      }
      return broadcastUpdate(chat, msg);
    }

    case 'react': {
      const chat = memberChat();
      if (!chat) return;
      const emoji = String(m.emoji || '');
      const msg = findMsg(chat, String(m.id));
      if (!msg || msg.deleted || msg.system) return;
      if (!REACTIONS.includes(emoji) && !PREMIUM_REACTIONS.includes(emoji)) return;
      if (PREMIUM_REACTIONS.includes(emoji) && tierOf(me) !== 'premium') return err('Эта реакция доступна с подпиской Premium');
      msg.reactions = msg.reactions || {};
      const had = (msg.reactions[emoji] || []).includes(me);
      // одна реакция от человека на сообщение, как в Telegram
      for (const e of Object.keys(msg.reactions)) {
        msg.reactions[e] = msg.reactions[e].filter((u) => u !== me);
        if (!msg.reactions[e].length) delete msg.reactions[e];
      }
      if (!had) (msg.reactions[emoji] = msg.reactions[emoji] || []).push(me);
      if (!Object.keys(msg.reactions).length) delete msg.reactions;
      return broadcastUpdate(chat, msg);
    }

    case 'pin': {
      const chat = memberChat();
      if (!chat) return;
      if (chat.type === 'channel' && !isAdmin(me)) return err('Закреплять могут только администраторы');
      if (m.id === null || m.id === undefined) {
        chat.pinned = null;
      } else {
        const msg = findMsg(chat, String(m.id));
        if (!msg || msg.deleted || msg.system) return;
        chat.pinned = msg.id;
      }
      touch('chats', chat.id);
      for (const member of chat.members) sendTo(member, { type: 'chat_update', chat: chatView(chat, member) });
      return;
    }

    // ------------------------------------------------ фото, голосовые, стикеры --
    case 'upload': {
      const chat = memberChat();
      if (!chat) return;
      const bad = canPost(chat);
      if (bad) return err(bad);
      const kind = m.kind === 'voice' ? 'voice' : m.kind === 'image' ? 'image' : null;
      const mime = String(m.mime || '').split(';')[0].trim().toLowerCase();
      const data = typeof m.data === 'string' ? m.data : '';
      if (!kind || !(kind === 'image' ? IMAGE_MIMES : VOICE_MIMES).includes(mime)) return err('Этот тип файла не поддерживается');
      const maxB64 = kind === 'image' ? photoLimit(me) : MEDIA_MAX_B64;
      if (data.length > maxB64 && data.length <= PHOTO_B64.premium) return err(kind === 'image' ? 'Фото слишком большое для вашего тарифа. Premium позволяет фото в высоком качестве до 16K' : 'Файл слишком большой');
      if (!data || data.length > maxB64 || !/^[A-Za-z0-9+/]+={0,2}$/.test(data)) return err('Файл слишком большой или повреждён');
      const media = { id: newId(), mime, size: Buffer.byteLength(data, 'base64') };
      if (kind === 'image') {
        media.w = clampInt(m.w, 1, 16384);
        media.h = clampInt(m.h, 1, 16384);
      } else {
        media.dur = clampInt(m.dur, 0, 300);
      }
      const message = { id: newId(), from: me, text: String(m.text || '').trim().slice(0, 1000), ts: Date.now(), kind, media };
      const reply = makeReply(chat, m.replyTo);
      if (reply) message.replyTo = reply;
      saveMedia(media.id, { mime, data })
        .then(() => {
          if (!getChat(chat.id)) return deleteMedia(media.id);
          pushMessage(chat, message);
          markRead(chat, me);
        })
        .catch((e) => {
          console.error('Не удалось сохранить файл:', e.message);
          err('Не удалось сохранить файл, попробуйте ещё раз');
        });
      return;
    }

    case 'get_media': {
      const chat = memberChat();
      const id = String(m.id || '');
      if (!chat) return;
      const owner = chat.messages.find((x) => x.media && x.media.id === id && !x.deleted);
      const missing = () => sendWs(ws, { type: 'media', id, missing: true });
      if (!owner) return missing();
      getMedia(id)
        .then((rec) => (rec ? sendWs(ws, { type: 'media', id, mime: rec.mime, data: rec.data }) : missing()))
        .catch(missing);
      return;
    }

    case 'send_sticker': {
      const chat = memberChat();
      if (!chat) return;
      const bad = canPost(chat);
      if (bad) return err(bad);
      const sticker = String(m.sticker || '');
      if (!STICKERS.includes(sticker) && !PREMIUM_STICKERS.includes(sticker)) return;
      if (PREMIUM_STICKERS.includes(sticker) && tierOf(me) !== 'premium') return err('Этот стикер доступен с подпиской Premium');
      const message = { id: newId(), from: me, text: '', ts: Date.now(), kind: 'sticker', sticker };
      const reply = makeReply(chat, m.replyTo);
      if (reply) message.replyTo = reply;
      pushMessage(chat, message);
      markRead(chat, me);
      return;
    }

    // ------------------------------------------------------------------ опросы --
    case 'send_poll': {
      const chat = memberChat();
      if (!chat) return;
      const bad = canPost(chat);
      if (bad) return err(bad);
      const question = String(m.question || '').trim().slice(0, 200);
      const texts = (Array.isArray(m.options) ? m.options : [])
        .map((o) => String(o || '').trim().slice(0, 100))
        .filter(Boolean);
      const options = [...new Set(texts)].slice(0, 10);
      if (!question) return err('Введите вопрос');
      if (options.length < 2) return err('Нужно хотя бы два разных варианта ответа');
      const message = {
        id: newId(),
        from: me,
        text: '',
        ts: Date.now(),
        kind: 'poll',
        poll: { question, multi: !!m.multi, closed: false, options: options.map((text) => ({ text, votes: [] })) },
      };
      const reply = makeReply(chat, m.replyTo);
      if (reply) message.replyTo = reply;
      pushMessage(chat, message);
      markRead(chat, me);
      return;
    }

    case 'poll_vote': {
      const chat = memberChat();
      if (!chat) return;
      const msg = findMsg(chat, String(m.id));
      if (!msg || msg.deleted || msg.kind !== 'poll' || msg.poll.closed) return;
      const idx = Number(m.option);
      if (!Number.isInteger(idx) || idx < 0 || idx >= msg.poll.options.length) return;
      const opt = msg.poll.options[idx];
      const had = opt.votes.includes(me);
      if (msg.poll.multi) opt.votes = opt.votes.filter((u) => u !== me);
      else for (const o of msg.poll.options) o.votes = o.votes.filter((u) => u !== me);
      if (!had) opt.votes.push(me); // повторное нажатие снимает голос
      return broadcastUpdate(chat, msg);
    }

    case 'poll_close': {
      const chat = memberChat();
      if (!chat) return;
      const msg = findMsg(chat, String(m.id));
      if (!msg || msg.deleted || msg.kind !== 'poll') return;
      if (msg.from !== me && !isAdmin(me)) return err('Завершить опрос может только автор');
      msg.poll.closed = true;
      return broadcastUpdate(chat, msg);
    }

    case 'read': {
      const chat = memberChat();
      if (chat) markRead(chat, me);
      return;
    }

    case 'typing': {
      const chat = memberChat();
      if (!chat || chat.type === 'channel') return;
      for (const member of chat.members) {
        if (member !== me) sendTo(member, { type: 'typing', chatId: chat.id, user: me });
      }
      return;
    }

    // -------------------------------------------------------------- монеты --
    case 'bonus': {
      const left = (meU.lastBonus || 0) + DAY_MS - Date.now();
      if (left > 0) {
        const h = Math.floor(left / 3600000);
        const min = Math.ceil((left % 3600000) / 60000);
        return err(`Бонус будет доступен через ${h ? h + ' ч ' : ''}${min} мин`);
      }
      const bonus = bonusFor(me);
      meU.coins = Math.min(MAX_COINS, meU.coins + bonus);
      meU.lastBonus = Date.now();
      touch('users', me);
      pushBalance(me);
      return info(`Ежедневный бонус: +${bonus} 🪙`);
    }

    case 'transfer': {
      const to = String(m.to || '').trim().toLowerCase();
      const amount = Number(m.amount);
      const target = getUser(to);
      if (!target || to === me || target.banned) return err('Получатель не найден');
      if (!Number.isInteger(amount) || amount < 1 || amount > 1e9) return err('Введите целое число монет от 1');
      if (meU.coins < amount) return err('Недостаточно монет');
      meU.coins -= amount;
      target.coins = Math.min(MAX_COINS, target.coins + amount);
      touch('users', me);
      touch('users', to);
      pushBalance(me);
      pushBalance(to);
      const dm = getOrCreateDm(me, to);
      pushMessage(dm, { id: newId(), from: me, text: `${me} отправил(а) ${to} ${amount} 🪙`, ts: Date.now(), system: true, tx: true });
      markRead(dm, me);
      return info(`Отправлено ${amount} 🪙 пользователю ${to}`);
    }

    // ------------------------------------------------- подарки и подписки --
    case 'send_gift': {
      const chat = memberChat();
      if (!chat) return;
      if (chat.type !== 'dm') return err('Подарки можно дарить только в личных чатах');
      const peer = chat.members.find((x) => x !== me);
      const pu = getUser(peer);
      if (!pu || peer === me || pu.banned) return err('Получатель не найден');
      const g = GIFTS.find((x) => x.id === m.giftId);
      if (!g) return err('Такого подарка нет');
      const price = giftPrice(me, g);
      if (meU.coins < price) return err('Недостаточно монет');
      const note = String(m.text || '').trim().slice(0, 200);
      meU.coins -= price;
      const entry = { id: newId(), gift: g.id, from: me, ts: Date.now(), note };
      pu.gifts = Array.isArray(pu.gifts) ? pu.gifts : [];
      pu.gifts.unshift(entry);
      if (pu.gifts.length > MAX_GIFTS) pu.gifts.length = MAX_GIFTS;
      touch('users', me);
      touch('users', peer);
      pushBalance(me);
      pushBalance(peer);
      const message = { id: newId(), from: me, text: note, ts: Date.now(), kind: 'gift', gift: { id: entry.id, gid: g.id, emoji: g.emoji, name: g.name, price: g.price } };
      const reply = makeReply(chat, m.replyTo);
      if (reply) message.replyTo = reply;
      pushMessage(chat, message);
      markRead(chat, me);
      return info(`Подарок «${g.name}» отправлен: ${peer}`);
    }

    case 'set_profile': {
      if ('bio' in m) {
        const bio = String(m.bio || '').replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, 150);
        if (bio) meU.bio = bio; else delete meU.bio;
      }
      if ('avatar' in m) {
        const av = cleanAvatar(m.avatar);
        if (m.avatar && !av) return err('Не удалось сохранить аватар: картинка слишком большая');
        if (av) meU.avatar = av; else delete meU.avatar;
        broadcastAll({ type: 'avatar', user: me, avatar: av });
      }
      touch('users', me);
      pushBalance(me);
      return info('Профиль сохранён');
    }

    case 'set_email': {
      const email = String(m.email || '').trim().toLowerCase();
      if (!email) {
        delete meU.email;
        touch('users', me);
        pushBalance(me);
        return info('Почта удалена из профиля');
      }
      if (email.length > 120 || !EMAIL_RE.test(email)) return err('Проверьте адрес почты');
      const owner = findByEmail(email);
      if (owner && owner !== me) return err('Эта почта уже используется другим аккаунтом');
      meU.email = email;
      touch('users', me);
      pushBalance(me);
      return info('Почта сохранена. Теперь можно входить по ней');
    }

    case 'set_rainbow': {
      if (!canRainbow(me)) return err('Радужный ник вам не выдан');
      if (m.on) delete meU.rainbowOff; else meU.rainbowOff = true;
      touch('users', me);
      pushBalance(me);
      broadcastAll({ type: 'rainbows', list: rainbowList() });
      return;
    }

    case 'send_gifts': {
      const chat = memberChat();
      if (!chat) return;
      if (chat.type !== 'dm') return err('Подарки можно дарить только в личных чатах');
      const peer = chat.members.find((x) => x !== me);
      const pu = getUser(peer);
      if (!pu || peer === me || pu.banned) return err('Получатель не найден');
      const items = (Array.isArray(m.items) ? m.items : []).slice(0, 12)
        .map((it) => ({ g: GIFTS.find((x) => x.id === (it && it.giftId)), n: Math.floor(Number(it && it.count)) }))
        .filter((it) => it.g && it.n >= 1);
      const total = items.reduce((a, it) => a + it.n, 0);
      if (!items.length) return err('Выберите подарки');
      if (total > 30) return err('За один раз можно отправить не больше 30 подарков');
      const cost = items.reduce((a, it) => a + giftPrice(me, it.g) * it.n, 0);
      if (meU.coins < cost) return err(`Недостаточно монет: нужно ${cost} 🪙`);
      const note = String(m.text || '').trim().slice(0, 200);
      meU.coins -= cost;
      pu.gifts = Array.isArray(pu.gifts) ? pu.gifts : [];
      const now = Date.now();
      const messages = [];
      items.forEach((it, idx) => {
        let firstId = null;
        for (let i = 0; i < it.n; i++) {
          const entry = { id: newId(), gift: it.g.id, from: me, ts: now, note: idx === items.length - 1 ? note : '' };
          if (!firstId) firstId = entry.id;
          pu.gifts.unshift(entry);
        }
        messages.push({
          id: newId(), from: me, text: idx === items.length - 1 ? note : '', ts: now + idx, kind: 'gift',
          gift: { id: firstId, gid: it.g.id, emoji: it.g.emoji, name: it.g.name, price: it.g.price, count: it.n },
        });
      });
      if (pu.gifts.length > MAX_GIFTS) pu.gifts.length = MAX_GIFTS;
      touch('users', me);
      touch('users', peer);
      pushBalance(me);
      pushBalance(peer);
      const reply = makeReply(chat, m.replyTo);
      if (reply) messages[0].replyTo = reply;
      for (const msg of messages) pushMessage(chat, msg);
      markRead(chat, me);
      return info(`Отправлено подарков: ${total} (−${cost} 🪙)`);
    }

    case 'my_gifts':
      return sendWs(ws, { type: 'my_gifts', gifts: giftsView(me) });

    case 'gift_sell': {
      const list = Array.isArray(meU.gifts) ? meU.gifts : [];
      const i = list.findIndex((x) => x.id === String(m.id));
      if (i < 0) return err('Подарок не найден');
      const g = GIFTS.find((x) => x.id === list[i].gift);
      const back = Math.floor((g ? g.price : 0) * GIFT_SELL);
      list.splice(i, 1);
      meU.coins = Math.min(MAX_COINS, meU.coins + back);
      touch('users', me);
      pushBalance(me);
      sendWs(ws, { type: 'my_gifts', gifts: giftsView(me) });
      return info(`Подарок обменян на ${back} 🪙`);
    }

    case 'get_profile': {
      const name = String(m.user || '').toLowerCase();
      const u = getUser(name);
      if (!u || u.banned) return err('Пользователь не найден');
      const sub = subOf(name);
      return sendWs(ws, {
        type: 'profile',
        user: name,
        role: roleOf(name),
        online: isOnline(name),
        lastSeen: u.lastSeen || null,
        sub: sub ? { plan: sub.plan, until: sub.until } : null,
        giftCount: Array.isArray(u.gifts) ? u.gifts.length : 0,
        gifts: giftsView(name).slice(0, 400),
        bio: u.bio || '',
        avatar: u.avatar || null,
      });
    }

    case 'subscribe': {
      const plan = PLANS.find((p) => p.id === m.plan);
      if (!plan) return err('Неизвестный тариф');
      const rank = { plus: 1, premium: 2 };
      const cur = subOf(me);
      if (cur && rank[cur.plan] > rank[plan.id]) return err('У вас уже активна более высокая подписка');
      if (meU.coins < plan.price) return err('Недостаточно монет');
      meU.coins -= plan.price;
      const base = cur && cur.plan === plan.id ? cur.until : Date.now();
      meU.sub = { plan: plan.id, until: base + SUB_MS };
      touch('users', me);
      pushBalance(me);
      broadcastAll({ type: 'subs', subs: subsMap() });
      return info(`Подписка ${plan.name} активна до ${fmtDate(meU.sub.until)}`);
    }

    case 'top': {
      const top = Object.entries(db.users)
        .filter(([, u]) => !u.banned)
        .sort((a, b) => b[1].coins - a[1].coins)
        .slice(0, 10)
        .map(([name, u]) => ({ username: name, coins: u.coins, role: roleOf(name) }));
      return sendWs(ws, { type: 'top', top });
    }

    case 'logout': {
      if (typeof m.token === 'string' && has(db.sessions, m.token)) {
        delete db.sessions[m.token];
        touch('sessions', m.token);
      }
      return;
    }
  }

  // ------------------------------------------------------- админ-команды --
  if (!String(m.type).startsWith('admin_')) return;
  if (!isAdmin(me)) return err('Нужны права администратора');
  const refreshUsers = () => sendWs(ws, adminSnapshot(ws.adminQuery));
  const target = getUser(String(m.user || '').toLowerCase()) ? String(m.user).toLowerCase() : null;

  switch (m.type) {
    case 'admin_users': {
      ws.adminQuery = String(m.query || '');
      return refreshUsers();
    }

    case 'admin_chats':
      return sendWs(ws, adminChatList());

    case 'admin_ban': {
      if (!canManage(me, target)) return err('Нельзя применить это действие к такому пользователю');
      const ban = !!m.banned;
      db.users[target].banned = ban;
      touch('users', target);
      if (ban) {
        dropSessions(target);
        kick(target, 'Ваш аккаунт заблокирован администратором');
      }
      info(ban ? `${target} заблокирован` : `${target} разблокирован`);
      return refreshUsers();
    }

    case 'admin_delete_user': {
      if (!canManage(me, target)) return err('Нельзя применить это действие к такому пользователю');
      removeUser(target);
      info(`Аккаунт ${target} удалён`);
      refreshUsers();
      return sendWs(ws, adminChatList());
    }

    case 'admin_reset_password': {
      const password = String(m.password || '');
      if (!canManage(me, target)) return err('Нельзя применить это действие к такому пользователю');
      if (password.length < 6) return err('Пароль должен быть не короче 6 символов');
      const salt = crypto.randomBytes(16).toString('hex');
      db.users[target].salt = salt;
      db.users[target].hash = hashPassword(password, salt);
      touch('users', target);
      dropSessions(target);
      kick(target, 'Пароль изменён администратором, войдите заново');
      return info(`Пароль пользователя ${target} изменён`);
    }

    case 'admin_coins': {
      if (!target) return err('Пользователь не найден');
      const amount = Number(m.amount);
      if (!Number.isInteger(amount) || Math.abs(amount) > 1e12) return err('Введите целое число');
      const u = db.users[target];
      const before = u.coins;
      u.coins = m.mode === 'set' ? Math.max(0, Math.min(MAX_COINS, amount)) : Math.max(0, Math.min(MAX_COINS, u.coins + amount));
      touch('users', target);
      pushBalance(target);
      if (target !== me && u.coins !== before) {
        const diff = u.coins - before;
        sendTo(target, { type: 'info', text: `Администратор изменил ваш баланс: ${diff > 0 ? '+' : ''}${diff} 🪙` });
      }
      info(`${target}: теперь ${u.coins} 🪙`);
      return refreshUsers();
    }

    case 'admin_role': {
      if (!isOwner(me)) return err('Назначать администраторов может только владелец');
      if (!target || isOwner(target)) return err('Нельзя изменить роль этого пользователя');
      db.users[target].admin = !!m.admin;
      touch('users', target);
      broadcastAll({ type: 'roles', admins: adminList() });
      pushBalance(target);
      info(m.admin ? `${target} теперь администратор` : `${target} больше не администратор`);
      return refreshUsers();
    }

    case 'admin_rainbow': {
      if (!isOwner(me)) return err('Выдавать радужный ник может только владелец');
      if (!target) return err('Пользователь не найден');
      if (isOwner(target)) return err('У владельца радужный ник уже есть');
      if (m.grant) db.users[target].rainbowGrant = true; else { delete db.users[target].rainbowGrant; delete db.users[target].rainbowOff; }
      touch('users', target);
      pushBalance(target);
      broadcastAll({ type: 'rainbows', list: rainbowList() });
      info(m.grant ? `${target} получил радужный ник 🌈` : `У ${target} убран радужный ник`);
      return refreshUsers();
    }

    case 'admin_sub': {
      if (!target) return err('Пользователь не найден');
      const plan = PLANS.find((p) => p.id === m.plan);
      const days = Math.max(0, Math.min(3650, Math.floor(Number(m.days) || 0)));
      if (!plan || !days) delete db.users[target].sub;
      else db.users[target].sub = { plan: plan.id, until: Date.now() + days * 86400000 };
      touch('users', target);
      pushBalance(target);
      broadcastAll({ type: 'subs', subs: subsMap() });
      info(plan && days ? `${target}: ${plan.name} на ${days} дн.` : `${target}: подписка снята`);
      return refreshUsers();
    }

    case 'admin_broadcast': {
      const text = String(m.text || '').trim().slice(0, 2000);
      if (!text) return err('Введите текст объявления');
      ensureAnnounce();
      for (const u of Object.keys(db.users)) if (!db.users[u].banned) addToAnnounce(u);
      pushMessage(db.chats[ANNOUNCE_ID], { id: newId(), from: me, text, ts: Date.now() });
      markRead(db.chats[ANNOUNCE_ID], me);
      return info(`Объявление отправлено: ${Object.keys(db.users).length} пользователям`);
    }

    case 'admin_delete_chat': {
      const chat = getChat(String(m.chatId || ''));
      if (!chat) return err('Чат не найден');
      removeChat(chat);
      info('Чат удалён');
      return sendWs(ws, adminChatList());
    }
  }
}

// ============================================================== HTTP-сервер ==

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.json': 'application/json; charset=utf-8',
  '.webmanifest': 'application/manifest+json; charset=utf-8',
};

const server = http.createServer((req, res) => {
  let urlPath;
  try {
    urlPath = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
  } catch {
    res.writeHead(400);
    return res.end('Bad request');
  }
  if (urlPath === '/health') {
    res.writeHead(200, { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store' });
    return res.end('ok');
  }
  if (urlPath === '/') urlPath = '/index.html';

  // В «собранной» версии (один файл) интерфейс встроен в сам server.js
  if (typeof EMBEDDED_ASSETS !== 'undefined' && Object.prototype.hasOwnProperty.call(EMBEDDED_ASSETS, urlPath)) {
    res.writeHead(200, {
      'Content-Type': MIME[path.extname(urlPath)] || 'application/octet-stream',
      'Cache-Control': 'no-cache',
    });
    return res.end(Buffer.from(EMBEDDED_ASSETS[urlPath], 'base64'));
  }

  const filePath = path.normalize(path.join(PUBLIC_DIR, urlPath));
  if (!filePath.startsWith(PUBLIC_DIR + path.sep)) {
    res.writeHead(403);
    return res.end('Forbidden');
  }
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      return res.end('Не найдено');
    }
    res.writeHead(200, {
      'Content-Type': MIME[path.extname(filePath)] || 'application/octet-stream',
      'Cache-Control': 'no-cache',
    });
    res.end(data);
  });
});

const wss = new WebSocketServer({ server, maxPayload: 10 * 1024 * 1024 }); // фото и голосовые идут как base64

wss.on('connection', (ws) => {
  ws.user = null;
  ws.isAlive = true;
  ws.on('pong', () => (ws.isAlive = true));
  ws.on('message', (raw) => {
    let m;
    try {
      m = JSON.parse(raw);
    } catch {
      return;
    }
    try {
      handle(ws, m);
    } catch (e) {
      console.error('Ошибка обработки сообщения:', e);
    }
  });
  ws.on('close', () => {
    const me = ws.user;
    if (!me) return;
    const set = clients.get(me);
    if (set) {
      set.delete(ws);
      if (set.size === 0) {
        clients.delete(me);
        const lastSeen = Date.now();
        if (getUser(me)) {
          db.users[me].lastSeen = lastSeen;
          touch('users', me);
        }
        broadcastAll({ type: 'presence', user: me, online: false, lastSeen });
      }
    }
  });
});

// отбрасываем «мёртвые» соединения
setInterval(() => {
  for (const ws of wss.clients) {
    if (!ws.isAlive) {
      ws.terminate();
      continue;
    }
    ws.isAlive = false;
    ws.ping();
  }
}, 30000);

async function shutdown() {
  try {
    await Promise.race([flushAll(), sleep(8000)]);
  } catch {
    /* ignore */
  }
  process.exit(0);
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

(async () => {
  await loadDb();
  migrate();
  server.listen(PORT, () => {
    console.log(`Мессенджер запущен: http://localhost:${PORT}`);
    console.log('Владельцы (админы): ' + ([...OWNERS].join(', ') || 'не заданы'));
  });
})();
